File: force-app/main/default/classes/ContactTriggerHandler.cls
```apex
public inherited sharing class ContactTriggerHandler {

    /**
     * Before insert: defaults MailingCountry from the related account's
     * BillingCountry and LeadSource from the account's AccountSource when
     * the contact values are blank. Uses one SOQL query for the whole batch.
     */
    public void beforeInsert(List<Contact> newRecords) {
        applyAccountDefaults(newRecords, true);
    }

    /**
     * Before update: defaults MailingCountry from the related account's
     * BillingCountry when the contact value is blank. LeadSource is only
     * defaulted on insert, matching the original trigger behaviour.
     */
    public void beforeUpdate(List<Contact> newRecords) {
        applyAccountDefaults(newRecords, false);
    }

    /**
     * After insert: if a new contact has a phone and its account has none,
     * the account's phone is set from the contact. When several new contacts
     * of the same account have a phone and the account has none, the first
     * contact in trigger order wins. All account updates are written with a
     * single DML statement.
     */
    public void afterInsert(List<Contact> newRecords) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newRecords) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : newRecords) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account account = accountsById.get(c.AccountId);
            // The queried account record is shared across contacts of the
            // same account, so once the phone is set on it, later contacts
            // see a populated phone and are skipped: the first contact in
            // trigger order wins, exactly like the original per-record logic.
            if (account == null || String.isNotBlank(account.Phone)) {
                continue;
            }
            account.Phone = c.Phone;
            accountsToUpdate.add(account);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    /**
     * Defaults contact fields from the related accounts. The accounts are
     * fetched with a single SOQL query for the entire trigger batch and the
     * contact records (Trigger.new) are modified in place, so no DML is
     * needed in the before contexts.
     */
    private void applyAccountDefaults(List<Contact> newRecords, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newRecords) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : newRecords) {
            if (c.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(c.AccountId);
            if (account == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = account.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = account.AccountSource;
            }
        }
    }
}
