@IsTest
private class OpportunitiesServiceTest {
    // Ids from fflib_IDGenerator are not in the org data, so tests never hit the database.
    private static final fflib_IDGenerator.IdGenerator ID_GENERATOR = new fflib_IDGenerator.IdGenerator();

    @IsTest
    static void testApplyDiscountsWithTooLowDiscountThrowsException() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        try {
            OpportunitiesService.applyDiscounts(new Set<Id>{ ID_GENERATOR.generate() }, 0);
            System.assert(false, 'Expected an OpportunitiesServiceException for a 0% discount.');
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            System.assertEquals(
                'Discount must be greater than 0 and at most 50 percent.',
                e.getMessage(),
                'Unexpected exception message for a 0% discount.'
            );
        }

        // Neither the domain nor the unit of work may be used.
        System.assertEquals(0, mocks.getCallCount(oppDomainConstructorMockId()), 'Domain constructor should not be invoked.');
    }

    @IsTest
    static void testApplyDiscountsWithNegativeDiscountThrowsException() {
        try {
            OpportunitiesService.applyDiscounts(new Set<Id>{ ID_GENERATOR.generate() }, -10);
            System.assert(false, 'Expected an OpportunitiesServiceException for a negative discount.');
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            System.assertEquals(
                'Discount must be greater than 0 and at most 50 percent.',
                e.getMessage(),
                'Unexpected exception message for a negative discount.'
            );
        }
    }

    @IsTest
    static void testApplyDiscountsWithTooHighDiscountThrowsException() {
        try {
            OpportunitiesService.applyDiscounts(new Set<Id>{ ID_GENERATOR.generate() }, 50.01);
            System.assert(false, 'Expected an OpportunitiesServiceException for a discount above 50%.');
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            System.assertEquals(
                'Discount must be greater than 0 and at most 50 percent.',
                e.getMessage(),
                'Unexpected exception message for a discount above 50%.'
            );
        }
    }

    @IsTest
    static void testApplyDiscountsWithNullDiscountThrowsException() {
