    public override void onValidate()
    {
        validateAmountIsNotNegative();

        if (getOperation() == 'update')
        {
            validateAmountNotChangedOnWonOpportunities();
        }
    }

    /**
     * Rule 1: Amount must not be negative (insert and update).
     */
    private void validateAmountIsNotNegative()
    {
        for (Opportunity record : (List<Opportunity>) Records)
        {
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }
        }
    }

    /**
     * Rule 2: On update, an opportunity that was already Closed Won before the
     * update cannot have its Amount changed. Changing the stage to Closed Won
     * and the Amount in the same update is allowed.
     */
    private void validateAmountNotChangedOnWonOpportunities()
    {
        // Query the pre-update database state in bulk: one SOQL, no per-record queries.
        Set<Id> recordIds = new Map<Id, SObject>(Records).keySet();

        Map<Id, Opportunity> existingOpportunities = new Map<Id, Opportunity>(
            [
                SELECT Id, StageName, Amount
                FROM Opportunity
                WHERE Id IN :recordIds
            ]
        );

        for (Opportunity record : (List<Opportunity>) Records)
        {
            Opportunity original = existingOpportunities.get(record.Id);
            if (original == null)
            {
                continue; // not an existing record
            }

            Boolean wasWonBeforeUpdate =
                original.StageName == 'Closed Won'
                && record.StageName == 'Closed Won';

            Boolean amountChanged =
                record.Amount == null
                    ? original.Amount != null
                    : original.Amount == null || record.Amount != original.getAmount();

            if (wasWonBeforeUpdate && amountChanged)
            {
                error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
            }
        }
    }
}
