{
    public Opportunities(List<Opportunity> sobjectList)
    {
        super(sobjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sobjectList)
        {
            return new Opportunities((List<Opportunity>) sobjectList);
        }
    }

    public override void onValidate()
    {
        validateAmountIsNotNegative();

        if (Trigger.isUpdating)
        {
            validateAmountNotChangedOnWonOpportunities();
        }
    }

    /**
     * Rule 1: On insert and on update, Amount must not be negative.
     * Bulk-safe; no SOQL.
     */
    private void validateAmountIsNotNegative()
    {
        for (Opportunity record : (List<Opportunity>) Records)
        {
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }
        }
    }

    /**
     * Rule 2: On update, an opportunity whose stage was already Closed Won
     * before the update cannot have its Amount changed. Closing as won and
     * changing Amount in the same update is allowed.
     *
     * Uses Trigger.oldMap (no SOQL) and getPopulatedFieldsAsMap() to detect
     * which fields the caller is actually changing — the same mechanism
     * fflib_SObjectDomain itself uses for change detection.
     */
    private void validateAmountNotChangedOnWonOpportunities()
    {
        for (Opportunity record : (List<Opportunity>) Records)
        {
            Opportunity oldRecord = Trigger.oldMap.get(record.Id);
            if (oldRecord == null)
            {
                continue;
            }

            // Precondition: the stage was already Closed Won *before* this
            // update, and the stage itself is not being changed now (closing
            // as won and changing Amount in the same update is allowed).
            Boolean wasAlreadyWon =
                oldRecord.StageName == 'Closed Won'
                && record.StageName == 'Closed Won'
                && !isChanged(record, Opportunity.StageName);

            if (wasAlreadyWon && isChanged(record, Opportunity.Amount))
            {
                error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
            }
        }
    }

    /**
     * Returns true when the given field is part of the incoming DML payload,
     * i.e. the caller is setting it in this update. This mirrors the change
     * detection used by fflib_SObjectDomain (no SOQL required).
     */
    private static Boolean isChanged(Opportunity record, Schema.SObjectField field)
    {
        return record.getPopulatedFieldsAsMap().containsKey(field.getDescribe().getName());
    }
}
