/**
 * RecurringGiftService
 *
 * Creates Enhanced Recurring Donations (npe03__Recurring_Donation__c) for
 * monthly giving sign-ups submitted by the nonprofit's donation form.
 *
 * Design notes:
 * - All requests are validated BEFORE any DML. If any request is invalid, a
 *   RecurringGiftException is thrown and nothing is inserted.
 * - NPSP generates the installment Opportunities itself; this class never
 *   creates Opportunities and never inserts or queries anything else.
 * - Limits: for 200 requests this service uses 0 SOQL queries and
 *   1 DML statement (a single bulk insert of all recurring donations).
 * - Day-of-month 31 is stored using NPSP's "always use last day of month"
 *   option (npsp__Always_Use_Last_Day_Of_Month__c = true), so that months
 *   with fewer than 31 days still generate an installment on the last day.
 *   Days 29 and 30 are stored literally, per the requirement.
 * - installments == null || installments == 0 -> open-ended recurring
 *   donation (npe03__Open_Ended_Status__c = 'Open').
 *   Otherwise -> fixed-length recurring donation with that number of
 *   planned installments (npe03__Open_Ended_Status__c = 'Fixed' and
 *   npe03__Installments__c set). NPSP derives the end date.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    /** One monthly giving sign-up received from the donation form. */
    @TestVisible
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'

        public GiftRequest(
            Id contactId,
            Decimal amount,
            Integer dayOfMonth,
            Date startDate,
            Integer installments,
            String paymentMethod
        ) {
            this.contactId = contactId;
            this.amount = amount;
            this.dayOfMonth = dayOfMonth;
            this.startDate = startDate;
            this.installments = installments;
            this.paymentMethod = paymentMethod;
        }
    }

    /** Valid payment methods accepted by the donation form. */
    private static final Set<String> VALID_PAYMENT_METHODS = new Set<String>{
        'Credit Card', 'ACH', 'Check'
    };

    /** Installment period value for a monthly schedule. */
    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    /** Schedule type for Enhanced Recurring Donations. */
    private static final String SCHEDULE_TYPE_MULTIYEAR = 'Multiyear';
    /** npe03__Open_Ended_Status__c value for open-ended donations. */
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    /** npe03__Open_Ended_Status__c value for fixed-length donations. */
    private static final String OPEN_ENDED_STATUS_FIXED = 'Fixed';

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests the sign-ups from the donation form
     * @return the new npe03__Recurring_Donation__c Ids, in request order
     * @throws RecurringGiftService.RecurringGiftException if any request is
     *         invalid (null contact, null/non-positive amount, dayOfMonth
     *         outside 1-31, or null startDate), before any DML is executed
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        // Null or empty input: nothing to do.
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        validateRequests(requests);

        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            donations.add(buildRecurringDonation(request));
        }

        // Single DML statement: bulk insert of all recurring donations.
        insert donations;

        List<Id> donationIds = new List<Id>();
        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }
        return donationIds;
    }

    /**
     * Validates every request and throws before any DML if any is invalid.
     * All problems are collected into a single exception message.
     */
    @TestVisible
    private static void validateRequests(List<GiftRequest> requests) {
        List<String> errors = new List<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            String label = 'Request ' + i;

            if (request == null) {
                errors.add(label + ': request is null.');
                continue;
            }
            if (request.contactId == null) {
                errors.add(label + ': contactId is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                errors.add(label + ': amount must be positive.');
            }
            if (request.dayOfMonth == null
                    || request.dayOfMonth < 1
                    || request.dayOfMonth > 31) {
                errors.add(label + ': dayOfMonth must be between 1 and 31.');
            }
            if (request.startDate == null) {
                errors.add(label + ': startDate is required.');
            }
            if (request.paymentMethod != null
                    && !VALID_PAYMENT_METHODS.contains(request.paymentMethod)) {
                errors.add(label + ': paymentMethod must be Credit Card, ACH or Check.');
            }
        }

        if (!errors.isEmpty()) {
            throw new RecurringGiftException(
                'Invalid recurring gift request(s): ' + String.join(errors, ' | ')
            );
        }
    }

    /**
     * Builds one Enhanced Recurring Donation for a validated request.
     * NPSP generates the installment Opportunities from these settings.
     */
    @TestVisible
    private static npe03__Recurring_Donation__c buildRecurringDonation(
        GiftRequest request
    ) {
        npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c(
            // The donor.
            npe03__Contact__c = request.contactId,
            // Each installment's amount.
            npe03__Amount__c = request.amount,
            // Monthly schedule.
            npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
            npsp__InstallmentFrequency__c = 1,
            npsp__RecurringType__c = 'Monthly',
            npe03__Schedule_Type__c = SCHEDULE_TYPE_MULTIYEAR,
            // Day of month, with 31 meaning "last day of month".
            npsp__Day_of_Month__c = request.dayOfMonth,
            npsp__Always_Use_Last_Day_Of_Month__c = (request.dayOfMonth == 31),
            // Scheduling anchor dates.
            npe03__Date_Established__c = request.startDate,
            npsp__StartDate__c = request.startDate,
            npe03__Next_Payment_Date__c = request.startDate,
            // Status and payment method as given.
            npsp__Status__c = 'Active',
            npsp__PaymentMethod__c = request.paymentMethod
        );

        // Open-ended vs fixed-length: installments null or 0 -> open-ended.
        if (request.installments == null || request.installments == 0) {
            donation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_OPEN;
        } else {
            donation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_FIXED;
            donation.npe03__Installments__c = request.installments;
            // npsp__EndDate__c is derived by NPSP from the installment count;
            // setting it here could conflict with NPSP's own calculation.
        }

        return donation;
    }
}
