/**
 * @description Collects the Ids of Opportunities which need to be pushed to the
 * ERP, so that the OpportunityErpSyncFinalizer DML finalizer can enqueue a
 * single OpportunityErpSyncJob per DML operation.
 *
 * Runs after insert (all records need syncing) and after update (only records
 * whose StageName changed need syncing).
 */
public with sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static final String FINALIZER_CLASS_NAME = 'OpportunityErpSyncFinalizer';

    /**
     * Keyed by the Id of the DML operation's top-level record set so that all
     * records from every chunk of the same DML statement (e.g. a 250-record
     * insert split into 200 + 50 chunks) land in the same collection, while
     * separate DML statements in the same transaction stay separate.
     */
    private static Map<Id, Set<Id>> idSetPerDmlOperation = new Map<Id, Set<Id>>();

    /**
     * Tracks which Ids are actually enqueued as Finalizers so that exactly one
     * finalizer is registered per DML operation, and only when at least one
     * opportunity needs syncing.
     */
    private static Set<Id> finalizedDmlOperations = new Set<Id>();

    private static String currentDmlOperationId {
        get {
            Id dmlOperationId = OpportunityTrigger.currentDmlOperationId;
            if (dmlOperationId == null) {
                // Fallback for when the framework has not set the Id
                dmlOperationId = OpportunityTrigger.dmlOperationId;
            }
            if (dmlOperationId == null) {
                // This should never happen when running through the framework,
                // but we guard against a null key in the map below.
                dmlOperationId = Id.valueOf('000000000000000AAA');
            }
            return dmlOperationId;
        }
    }

    private static void collectForErpSync(List<Opportunity> triggerNew) {
        Set<Id> idsToSync = idSetPerDmlOperation.get(currentDmlOperationId);
        if (idsToSync == null) {
            idsToSync = new Set<Id>();
            idSetPerDmlOperation.put(currentDmlOperationId, idsToSync);
        }
        idsToSync.addAll(new Map<Id, SObject>(triggerNew).keySet());
        attachFinalizerForCurrentDmlOperation();
    }

    private static void attachFinalizerForCurrentDmlOperation() {
        Id dmlOperationId = currentDmlOperationId;
        if (finalizedDmlOperations.contains(dmlOperationId)) {
            // A finalizer has already been registered for this DML operation.
            return;
        }
        finalizedDmlOperations.add(dmlOperationId);
        TriggerBase.waitToFinalize(FINALIZER_CLASS_NAME);
    }

    public void afterInsert(List<SObject> triggerNew) {
        collectForErpSync((List<Opportunity>) triggerNew);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Opportunity> newRecs = (List<Opportunity>) triggerNew;
        List<Opportunity> oldRecs = (List<Opportunity>) triggerOld;
        List<Opportunity> changed = new List<Opportunity>();
        for (Integer i = 0; i < newRecs.size(); i++) {
            if (newRecs[i].StageName != oldRecs[i].StageName) {
                changed.add(newRecs[i]);
            }
        }
        if (!changed.isEmpty()) {
            collectForErpSync(changed);
        }
    }
}
