/**
 * @description DML finalizer which enqueues exactly one OpportunityErpSyncJob
 * per DML operation, carrying the Ids of all opportunities from that operation
 * which need syncing. Enqueues nothing when no opportunity needs syncing.
 *
 * Registered with the DML_Finalizer__mdt record OpportunityErpSyncFinalizer
 * (order 10).
 *
 * The framework invokes every registered DML finalizer at the end of every DML
 * operation it handles, regardless of the sObject type, so this class must
 * self-filter on the sObject type and on the presence of collected Ids, and
 * must never perform DML.
 */
public with sharing class OpportunityErpSyncFinalizer
    implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        // The framework calls every finalizer for every DML operation, whatever
        // the sObject. Only react to Opportunity DML.
        if (context.getSObjectType() != Opportunity.SObjectType) {
            return;
        }

        Set<Id> idsToSync = TA_Opportunity_CollectForErpSync.getCollectedIds(context.getDmlOperationKey());
        if (idsToSync == null || idsToSync.isEmpty()) {
            return;
        }

        System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
        TA_Opportunity_CollectForErpSync.clearCollectedIds(context.getDmlOperationKey());
    }
}
